140	.hero-oh{background:var(--grey);}
141	.hero-nv{background:var(--grey);}
142	.hero-nh{background:var(--mint);}
143	.hero-h1{max-width:14ch;}
144	
145	.dither-layer{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;}
146	.color-layer{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;}
147	
148	/* card: a physical object (light stock, ink edge, hard offset shadow) so
149	   it reads against a black cell instead of disappearing into it. ~1.6x
150	   the R1 size at 1440 (was ~340px wide, now ~520px), 85:55 kept. */
151	.card-anchor{
152	  position:absolute;left:75%;top:50%;
153	  width:min(36vw,520px);
154	  aspect-ratio:85/55;
155	  transform:translate(-50%,-50%);
156	  perspective:1600px;
157	  z-index:5;
158	  pointer-events:none;
159	}
160	@media (max-width:767px){ .card-anchor{left:50%;top:120vw;width:min(74vw,380px);} }
161	.card-flip{
162	  width:100%;height:100%;position:relative;
163	  transform-style:preserve-3d;
164	  box-shadow:10px 10px 0 0 #000;
165	}
166	.face{
167	  position:absolute;inset:0;
168	  background:#fff;
169	  backface-visibility:hidden;
170	  border:1px solid #000;
171	  overflow:hidden;
172	}
173	/* A visible white mat around the photo, not a full-bleed image: a card
174	   that is a photo edge-to-edge reads as "the photo", not as "a light
175	   stock object sitting on the cell" - the mat is what makes the white
176	   stock actually visible against a black ÖH ground. */
177	.face--front{background:#fff;padding:6%;}
178	/* R6 bugfix: kontakt's front is a <button> wrapping <span>s (spans, unlike
179	   hero's <div>s, default to display:inline) - an inline, merely
180	   position:relative .photo never gets a real box (width/height are ignored
181	   on non-replaced inline elements), so it collapsed to a ~2px sliver and
182	   the absolutely-positioned img inside inherited that zero-size containing
183	   block. display:block here makes both tags behave identically. */
184	.face--front .photo{display:block;position:relative;width:100%;height:100%;overflow:hidden;border:1px solid rgba(0,0,0,.5);}
185	.face--back{
186	  transform:rotateY(180deg);
187	  background:#fff;color:var(--ink);
188	  display:flex;flex-direction:column;justify-content:center;gap:10px;padding:6% 8%;
189	}
190	.face--front img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;}
191	.mark-dock{position:absolute;top:9%;left:9%;width:14%;z-index:2;}
192	.mark-dock svg{width:100%;height:auto;fill:#fff;filter:drop-shadow(0 0 3px rgba(0,0,0,.7));}
193	.card-mark{font-size:clamp(20px,2.6vw,32px);letter-spacing:-.02em;margin:0;}
194	.card-kicker{font-family:"Geist Mono";font-weight:400;font-size:clamp(11px,1.1vw,14px);opacity:.65;margin:2px 0 0;}
195	.card-rule{border:0;border-top:1px solid rgba(0,0,0,.25);margin:6px 0;width:100%;}
196	.card-services{display:flex;gap:10px;font-family:"Geist Mono";font-weight:400;font-size:clamp(10px,1.1vw,13px);}
197	.card-cta{font-size:clamp(13px,1.5vw,18px);text-decoration:underline;margin-top:4px;align-self:flex-start;}
198	/* H5: the hero CTA takes a click only once the back faces the reader */
199	.card-anchor.is-back .card-cta{pointer-events:auto;cursor:pointer;}
200	
201	/* ------------------------------------------------------------- tes */
202	.tes-top{background:var(--black);color:var(--paper);padding:calc(var(--cellpad)*2) var(--cellpad);}
203	.tes-top .headline-50{max-width:22ch;}
204	/* R7: the approved breaks "Det första / intrycket / är digitalt." came from
205	   splitting with the fallback font's metrics. With Geist preloaded the split
206	   saw "intrycket är" fit on one line, so the width is now set where the
207	   approved breaks fall (between 4.47 em and 5.09 em), whenever the font loads. */
208	@media (min-width:768px){ .tes-top .headline-50{max-width:4.75em;} }
209	/* R9 §2: the Hyperborea frame and its list are gone. Two statements share one pinned
210	   cell: A stands, its words sink out of their line masks while B's letters rise in the
211	   same place, then B stands. Desktop stacks them in one grid area at the optical centre
212	   (block centre ~45 % of the viewport, Anton 2026-10-03); mobile has no pin and stacks
213	   them in flow. */
214	.tes-stage{display:grid;}
215	.tes-b-text{display:block;}
216	.tes-stage > *{grid-area:1 / 1;align-self:center;}  /* R9 §5: A is shorter than B; centred on its own it sat at .371 */
217	@media (min-width:768px){
218	  .tes-top{min-height:calc(100svh - 48px);display:flex;flex-direction:column;justify-content:center;padding-bottom:calc(var(--cellpad)*2 + 18svh);}  /* measured centre .437 at 1440x900 */
219	}
220	@media (max-width:767px){
221	  .tes-stage > .tes-b{grid-area:2 / 1;margin-top:calc(var(--headline-50) * .6);}
222	}
223	.tes-stage.tes-flow > .tes-b{grid-area:2 / 1;margin-top:calc(var(--headline-50) * .6);}  /* a11y H1 fallback, see JS */
224	.tes-stage.tes-flow > *{max-width:none;overflow-wrap:anywhere;}  /* spaced "intrycket" outgrew the 4.75em measure */
225	
226	/* ------------------------------------------------------------- process */
227	.process-row{}
228	.process-left{background:var(--grey);}
229	.process-sticky{position:sticky;top:calc(48px + var(--cellpad));}
230	.process-kicker{margin-bottom:14px;}
231	.process-title{margin:0 0 18px;max-width:11ch;}
232	.process-lock{max-width:32ch;opacity:.8;}
233	.process-image{position:relative;margin-top:32px;aspect-ratio:1/1;width:100%;max-width:680px;border:1px solid #000;overflow:hidden;}
234	.process-right{background:var(--black);color:var(--paper);padding:0;}
235	.process-steps{list-style:none;}
236	.process-row-item{display:grid;grid-template-columns:56px 1fr;gap:14px;padding:22px var(--cellpad);border-top:1px solid #000;}
237	.process-row-item:first-child{border-top:none;}
238	.process-num{font-family:"Geist Mono";font-weight:400;font-size:13px;padding-top:4px;}
239	.process-step-title{margin:0 0 6px;}
240	.process-p{color:#bdbdbd;max-width:56ch;font-size:15px;}
241	
242	/* ------------------------------------------------------------- exempelcase */
243	/* R5 §A bugfix: 0.6x bottom padding (12px) was less than the SplitText
244	   mask-breathe allowance (0.16em, ~16-20px at this clamp size) needs to
245	   clear the word's own descenders before the cell's overflow:hidden edge
246	   - verify_motion.py's legibility scan caught the word's rendered box
247	   (with its mask wrapper's padding-bottom) genuinely sitting a few px
248	   below the cell's clip boundary at every scroll position (0vh visible,
249	   not >=40vh). Matching the top padding removes the clip entirely. */
250	.case-word-cell{padding:calc(var(--cellpad)*1.4) var(--cellpad) calc(var(--cellpad)*1.4 + 4px);overflow:hidden;}
251	.case-word-cell .headline-50{max-width:100%;}
252	
253	/* R5 §B1: väljaren - två knappar, skarpa 1440x900-vyer, ingen beskärande zoom */
254	.case-picker-cell{padding:0 var(--cellpad) calc(var(--cellpad)*1.2);background:#000;}
255	.case-picker{display:grid;gap:1px;background:#000;}
256	.case-choice{
257	  display:block;width:100%;margin:0;padding:0;border:0;background:var(--paper);color:inherit;
258	  font:inherit;text-align:left;cursor:pointer;-webkit-appearance:none;appearance:none;
259	}
260	.case-choice-frame{position:relative;display:block;aspect-ratio:16/10;overflow:hidden;background:var(--grey);}
261	.case-choice-frame img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;transform:scale(1);transition:transform .7s cubic-bezier(.23,1,.32,1);}
262	@media (hover:hover){
263	  .case-choice:hover .case-choice-frame img,
264	  .case-choice:focus-visible .case-choice-frame img{transform:scale(1.04);}
265	}
266	.case-choice:focus-visible{outline:3px solid var(--black);outline-offset:-3px;}
267	.case-choice-meta{display:block;padding:16px var(--cellpad) 20px;border-bottom:4px solid transparent;}
268	.case-choice[aria-pressed="true"] .case-choice-meta{border-bottom-color:var(--mint);}
269	.case-choice-meta .h3{display:block;margin-bottom:4px;font-size:22px;}
270	
271	/* ------------------------------------------------------------- showcase (B2/C) */
272	.showcase-stage{display:grid;grid-template-columns:1fr;gap:1px;background:#000;}
273	/* R7 (H13): while the stage is more than 1.5 viewports away it is not drawn.
274	   Every ScrollTrigger refresh measured the pinned stage in a state Chrome
275	   logged as a 0.947 layout shift (two at load, CLS 1.89) although nothing
276	   moved on screen; an invisible box is not counted. Toggled by an
277	   IntersectionObserver in both directions, never while it can be seen. */
278	.showcase-stage.is-far, .showcase-stage.is-far *{visibility:hidden !important;}
279	/* H10 (R7): the showcase pins only where its side column fits. Below 561 px of height (768x432 = 200 % zoom) it takes the stacked layout, so no step text is clipped and the wheel never scrolls an inner panel. */
280	@media (min-width:768px) and (min-height:561px){ .showcase-stage{grid-template-columns:7fr 5fr;} }
281	.showcase-embed-cell{padding:0;background:var(--paper);position:relative;overflow:hidden;}
282	.showcase-embed-cell .showcase-frame-wrap{position:relative;width:100%;height:100%;overflow:hidden;background:var(--paper);}
283	.showcase-embed-cell .showcase-poster{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;object-position:top center;}
284	.showcase-embed-cell iframe{
285	  position:absolute;top:0;left:0;width:1440px;height:900px;border:0;background:var(--paper);
286	  transform-origin:top left;pointer-events:none;opacity:0;
287	}
288	@media (max-width:767px), (max-height:560px){
289	  .showcase-embed-cell{position:sticky;top:48px;height:56svh;z-index:2;}
290	}
291	@media (min-width:768px) and (max-height:560px){ .showcase-embed-cell{height:45svh;} }
292	@media (min-width:768px) and (min-height:561px){
293	  /* R6 §3, two stacked causes, both fixed here:
294	     1) .showcase-side's natural content (all 5/6 rows, R5's rise-mask kept
295	        every body visible at once) was taller than the embed cell's
296	        explicit height. A CSS grid item with an explicit height does not
297	        stretch to match a taller sibling's row track - the TRACK grows to
298	        fit the tall side instead, leaving the embed cell short of the
299	        row's actual height by the difference (measured ~110px), exposing
300	        the stage's own black gap background below the frame. Pinning both
301	        columns to the SAME explicit height (with the side's own
302	        overflow-y:auto as a never-clip safety net) makes them structurally
303	        impossible to mismatch, regardless of how much text a future edit
304	        adds.
305	     2) That explicit height was `100svh - 48px`, sized to sit BELOW the
306	        48px sticky topline - but the pin (`start:'top top'`) puts the
307	        section's rendered top at the viewport's own y:0, with the topline
308	        merely painted on top of (not offsetting) its first 48px. The
309	        result: content correctly avoids the topline visually, but then
310	        runs 48px short of the viewport's bottom edge, showing the stage's
311	        black background as a trailing band under both columns (measured:
312	        embed/side bottom at 852 of a 900-tall viewport). Hero's own pin
313	        has this identical 48px arithmetic and gap - invisible there only
314	        because it lands on the page's own black background either side.
315	        Showcase's is visible because there's real content flush above it.
316	        Fixed the same way hero's is invisible: fill the FULL viewport
317	        (100svh) - the topline still visually covers the top 48px (it's
318	        position:sticky, z-index:40, opaque), but the bottom now lands
319	        exactly on the viewport edge, so no gap is left to expose.
320	
321	     R7 runda 2, fynd 1: that "topline merely painted on top" claim was
322	     wrong for `.showcase-head`'s own rubrik - the topline IS opaque and
323	     DOES cover whatever renders in its first 48px; it just happened not to
324	     matter for hero (dark ground either side). Here `.showcase-head`'s
325	     headline-40 sits flush at the pinned section's very top edge, so its
326	     cap-height rendered UNDER the topline and got visually sheared (lead's
327	     through-05..through-12, 2026-09-25). Fix: pin the section 48px lower
328	     instead of hiding 48px under an opaque bar - `start:'top top+=48'` on
329	     the ScrollTrigger (setupDesktopEngine) puts the section's rendered top
330	     at y:48, exactly below the topline, and both cell heights shrink by
331	     the same 48px so the bottom still lands flush on the viewport edge -
332	     the R6 §3 gap this block fixed doesn't reopen, because now BOTH the
333	     offset and the height account for the topline, not just the height. */
334	  .showcase-embed-cell{height:calc(100svh - 48px);}
335	  .showcase-side{height:calc(100svh - 48px);overflow-y:auto;}
336	}
337	.showcase-side{display:grid;grid-template-rows:auto 1fr;gap:1px;background:#000;}
338	.showcase-panel{display:contents;}
339	.showcase-head{padding:calc(var(--cellpad)*1.4) var(--cellpad);color:var(--paper);}
340	/* H7: the frames are inert previews; the site itself opens from here */
341	.showcase-open{display:inline-flex;align-items:center;min-height:32px;margin-top:10px;font-size:16px;letter-spacing:-.01em;text-decoration:underline;text-underline-offset:3px;}
342	.showcase-open:focus-visible{outline:2px solid var(--paper);outline-offset:2px;}
343	.showcase-head .headline-40{margin-bottom:8px;}
344	
345	/* R7 §C: the accordion ledger (R6 §1/§2) is replaced on desktop by a single
346	   crossfading box - one background for the whole "ruta", every step
347	   grid-stacked in one cell and GSAP-scrubbed by the showcase pin's onUpdate
348	   (never a class-toggle). Mobile keeps R6's stacked-rows layout unchanged;
349	   only its opacity mechanism changes (measured contrast fix, see below). */
350	.showcase-row{padding:var(--cellpad);display:flex;flex-direction:column;justify-content:center;}
351	.showcase-row h3{margin-bottom:0;}
352	.showcase-row p{max-width:52ch;font-size:15px;margin-top:8px;}
353	/* R8 mobil: ingressen ett steg större än dagens 15 px, andra stycket som i dag */
354	.showcase-row .showcase-lede{font-size:17px;line-height:1.4;}
355	
356	@media (min-width:768px) and (min-height:561px){
357	  /* R6 runda 6 (F-019/F-022): tre celler i sidans eget rutverk (gap:1px,
358	     background:#000 skiner igenom som fog, varje cell sin egen bakgrund) -
359	     räknarcellen (auto), textcellen (auto, satt av det längsta stegets
360	     höjd via samma grid-area:1/1-stapling som förut) och en ny detaljcell
361	     (1fr, fyller resten) som visar en bild ur den valda sajten per steg.
362	     Den lodräta stegskalan (R3-R4) är borttagen helt - Anton (F-022):
363	     "Det ser ut som något ofärdigt". Tom yta löses nu med riktigt innehåll
364	     (en bild ur arbetet), inte med ett dekorativt streck. */
365	  /* R8 (Anton 2026-09-29, "ta bort rutorna"): EN yta under casehuvudet, NOT
366	     tre celler med fogar. Samma tre rader i gridden (räknare, text, lupp), men
367	     gap 0 och en enda bakgrund på behållaren: inga cellkanter, ingen
368	     bakgrundsväxling, inga skarvar mellan räknaren, texten och luppen. */
369	  .showcase-rows{display:grid;grid-template-rows:auto auto 1fr;gap:0;height:100%;position:relative;}
370	  .showcase-panel--calyx .showcase-rows{background:var(--paper);color:var(--ink);}
371	  .showcase-panel--horai .showcase-rows{background:var(--black);color:var(--paper);}
372	  /* räknaren och mintspåret: en rad direkt på ytan, utan box (skyddad effekt) */
373	  .showcase-box-head{padding:var(--cellpad) var(--cellpad) 0;}
374	  .showcase-counter{display:block;font-size:13px;margin-bottom:10px;}
375	  .showcase-track{position:relative;height:4px;}
376	  .showcase-track::before{content:'';position:absolute;top:50%;left:0;right:0;height:1px;background:#000;transform:translateY(-50%);}
377	  .showcase-panel--horai .showcase-track::before{background:var(--paper);opacity:.3;}
378	  .showcase-track-fill{position:absolute;top:0;left:0;width:100%;height:4px;background:var(--mint);transform-origin:0 50%;transform:scaleX(0);}
379	  .showcase-steps{display:grid;}
380	  /* R3 §4 (F-019): rubriken får aldrig ta över - sajten är huvudsaken,
381	     rutan är bildtexten. h3 tillbaka i rubrikskala (30px), inte
382	     headline-40-tokenet R2 lånade; jättesiffran är borttagen. */
383	  /* R6b: toppjusterad. Centrerad (basregeln) satte stegrubriken 14 px lägre i
384	     steg med tre rader än i steg med fyra, så rubriken hoppade vid varje byte. */
385	  /* R8: texten tar mer plats - rubrik i h3-skala (30 px, F-019), ingress
386	     20-22 px i full textfärg, andra stycket 16-17 px i sekundärfärg (mätt
387	     >= 4,5:1 per grund). Båda följer fönsterhöjden så att det längsta steget
388	     ryms vid 1280x800. Mått högst 46ch, luft på 8-skalan (16/16). */
389	  .showcase-steps{padding-top:32px;}
390	  /* 16 px under texten: de osynliga stegens y:12 (övertoningen) ryms i raden */
391	  .showcase-row{grid-area:1/1;padding:0 var(--cellpad) 16px;justify-content:flex-start;}
392	  .showcase-row h3{font-size:30px;line-height:1.15;font-weight:500;}
393	  .showcase-row p{max-width:46ch;margin-top:16px;}
394	  .showcase-row .showcase-lede{font-size:clamp(20px, calc(12px + 1vh), 22px);line-height:1.4;letter-spacing:-.01em;}
395	  /* R8: under ca 860 px höjd tar texten sina nedre värden (h3 28, radavstånd
396	     1,35/1,5, 24 px överst) så att luppen behåller en läsbar storlek. */
397	  @media (max-height:860px){
398	    .showcase-steps{padding-top:24px;}
399	    .showcase-row h3{font-size:28px;}
400	    .showcase-row .showcase-lede{line-height:1.35;}
401	  }
402	  /* detaljcellen: en <figure> per steg, grid-stackad (samma grid-area:1/1-
403	     teknik som .showcase-row ovan), färglager under och ett dither-rutnät
404	     ovanpå (buildTileGrid, samma mekanism som #kontakt/tes-bilden) som
405	     löses upp i den skrubbade pin-tidslinjen (C.tl, se buildStepTimelines).
406	     Calyx grå grund (dither svart-på-grått), Hōrai svart grund (dither
407	     vitt-på-svart) - samma två grundfärger dither.py redan producerar. */
408	  /* R6b: bilden är ett förstoringsglas (2,5-3x iframen) tagen i exakt cellens
409	     proportion vid 1440x900 (599,6/426,5 = 1,4058). Vid andra fönster varierar
410	     cellen från 0,63 (2560x1440) till 1,59 (1280x800); figuren låses därför
411	     till bildens proportion och passas in (contain) med container-enheter, så
412	     att färglagret och rutnätet ovanpå alltid täcker samma yta. Med cover
413	     klipptes luppen (adressen, priset) och rutorna gled ur linje mot färgen. */
414	  /* R8b (F-019: sajten är huvudsaken, inget får täcka ramen): luppen är ett
415	     band i kolumnens fulla bredd, kant i kant mot vänster, höger och botten,
416	     utan ram, inset eller skugga, NOT ett utklipp över skarven. Bandets höjd
417	     är det som blir kvar under det längsta steget (1fr), 24 px under texten
418	     (16 i raden + 8 här). Utsnittet är cover: figuren behåller bildens
419	     proportion (så att dither-rutnätet ligger kvar på färgen, R6b) och
420	     överfyller bandet, som klipper; --fx/--fy per figur är object-position
421	     som bråk, valt så att loupe.py STEPS mål står kvar i bild. Under 160 px
422	     band döljs luppen: texten vinner. */
423	  .showcase-detail{position:relative;overflow:hidden;min-height:0;margin-top:8px;container-type:size;}
424	  .showcase-figure{--fw:max(100cqw, calc(100cqh * 1.4058));position:absolute;width:var(--fw);aspect-ratio:1.4058;left:calc((100cqw - var(--fw)) * var(--fx, .5));top:calc((100cqh - var(--fw) / 1.4058) * var(--fy, .5));margin:0;opacity:0;}
425	  @container (max-height:159.98px){ .showcase-figure{display:none;} }
426	  .showcase-figure:first-child{opacity:1;}
427	  .showcase-figure img{position:absolute;inset:0;width:100%;height:100%;object-fit:fill;}
428	}
429	@media (max-width:767px), (max-height:560px){
430	  /* R7 runda 2, fynd 2: .showcase-embed-cell (position:sticky) satt över
431	     .showcase-side (head + rader) i normalt dokumentflöde, så när huvudet
432	     ("Hōrai") rullade upp genom den redan-klistrade ramen (z-index:2) klipptes
433	     det mot ramens underkant (lead: through-02/03). Huvudet ska stå helt
434	     synligt INNAN raderna - och innan ramen - börjar klistra, så .showcase-side
435	     görs display:contents här (bara mobil) för att lyfta .showcase-head och
436	     .showcase-rows till .showcase-stage's egna grid-items, och ordnas om med
437	     `order`: huvud (1) -> ram (2, där klistringen börjar) -> rader (3). */
438	  .showcase-side{display:contents;}
439	  .showcase-head{order:1;}
440	  .showcase-embed-cell{order:2;}
441	  .showcase-rows{display:flex;flex-direction:column;gap:0;background:#000;order:3;}
442	  /* R6 runda 6: .showcase-box-head hålls INTE display:none längre. Mätt
443	     (shots/r6-mobile-before, före denna runda): den borttagna stegskalan
444	     (.showcase-scale) hade ALDRIG en egen mobilregel, så dess räknartext
445	     redan föll igenom osynligt formaterad, som en enkel textrad i
446	     .showcase-rows egen svarta gap-bakgrund, ovanpå .showcase-embed-cell.
447	     Räknaren (nu flyttad hit) måste fortsätta synas EXAKT så - briefen
448	     ("mobil oförändrad") gäller även denna oavsiktliga men redan existerande
449	     synlighet. .showcase-track har fortfarande ingen mobilstorlek (dess
450	     height/position-regler ligger kvar i 768px-blocket ovan) och kollapsar
451	     därför osynligt till 0px, precis som förut. */
452	  .showcase-detail{display:none;}
453	  .showcase-steps{display:contents;}
454	  /* R8: raderna utan rutor - en yta per case, luften skiljer raderna åt, NOT
455	     randiga celler med svarta fogar. Den aktiva raden står i 1, de andra i
456	     MOBILE_INACTIVE_OPACITY (mätt >= 4,5:1 på båda styckena). */
457	  .showcase-panel--calyx .showcase-row{background:var(--paper);}
458	  .showcase-panel--horai .showcase-row{background:var(--black);color:var(--paper);}
459	  .showcase-panel--horai .showcase-row p{color:var(--paper-2);}
460	  .showcase-panel--horai .showcase-row .showcase-lede{color:var(--paper);}
461	  .showcase-rows .showcase-row{padding:24px var(--cellpad);}
462	}
