493	/* ------------------------------------------------------------- kontakt (R5 §C: heron speglad) */
494	.kontakt-quad{
495	  position:relative;display:grid;gap:1px;background:#000;min-height:100svh;
496	  grid-template-columns:1fr 1fr;grid-template-rows:1fr 1fr;
497	  grid-template-areas:"ov oh" "nv nh";
498	}
499	.kontakt-q{position:relative;overflow:hidden;padding:var(--cellpad);}
500	.kontakt-q--ov{grid-area:ov;background:var(--black);color:var(--paper);display:flex;flex-direction:column;justify-content:flex-end;gap:32px;}  /* R9 §4: >= the headline's x-height (10 px left the lede touching it) */
501	/* R6 §4: headline-40 is tuned for a single "jätteord" (hero, case names) -
502	   at this cell's half-page width, a four-word sentence in it ran past the
503	   ÖV/ÖH seam (measured x>720 at 1440, into the card's own space). A
504	   smaller, dedicated clamp - same family as the old kontakt-giant's - fits
505	   three lines comfortably inside the cell at 1440/1280/768, verified with
506	   getBoundingClientRect against the cell box, not eyeballed. */
507	.kontakt-q--ov h2{
508	  font-size:clamp(1.75rem, 1.1rem + 2.6vw, 3.4rem);line-height:1.05;
509	  letter-spacing:-.03em;font-weight:500;max-width:12ch;
510	}
511	.kontakt-q--ov p{max-width:32ch;font-size:15px;}
512	.kontakt-q--oh{grid-area:oh;background:var(--paper);}
513	.kontakt-q--nv{grid-area:nv;background:var(--grey);padding:0;}
514	.kontakt-q--nh{grid-area:nh;background:var(--mint);}
515	@media (max-width:767px){
516	  /* R6 §7: nh gets more room than ov/nv (was the same minmax(60vw) as
517	     both) - a 3D Y-axis rotation's perspective projection genuinely bulges
518	     a flat card's rendered bounding box taller at the near edge as it
519	     turns (measured: +/-28px top/bottom at 1200px perspective, still
520	     +/-24px at 3000px - foreshortening a rotated rectangle really does
521	     grow its axis-aligned bbox, not a rounding artefact), and centring an
522	     88%-wide card in a 60vw-tall row left only ~27px clearance to the
523	     subline above - not enough to survive that bulge at any angle in the
524	     0-180deg sweep. */
525	  .kontakt-quad{grid-template-columns:1fr;grid-template-rows:minmax(60vw,auto) minmax(76vw,auto) minmax(60vw,auto);grid-template-areas:"ov" "nh" "nv";min-height:auto;}
526	  .kontakt-q--oh{display:none;}
527	}
