529	/* the card sits on the crossing of all four quadrants (a grid item that
530	   spans the full 2x2 and centres itself), mirroring heron's own card. On
531	   mobile it drops into the mint cell's own grid area instead, 88% wide. */
532	/* R6 §4/§7: centred on the FULL 2x2 crossing put the card's top edge only
533	   ~15-50px below the headline row at rest, with zero margin for the flip's
534	   lift or the hover-tilt's foreshortening - both could (and did, measured)
535	   bring the card within single-digit px of "verksamhet.". Spanning only
536	   the LOWER row (grid-row:2, still centred horizontally on the vertical
537	   seam = still "on the crossing") puts the card inside the NV/NH half
538	   entirely, with a full row-height of clearance above it before ÖV even
539	   starts. */
540	/* R9 §4b: the card sat centred in the LOWER row (75 % down the section), so it arrived
541	   long after the heading (Anton: "hamnar jättelångt ned"). It now sits where heron's card
542	   sits - on the horizontal seam of the RIGHT column - which is the mirror the section is
543	   built on, puts the card at the section's middle, and keeps it clear of the heading in
544	   ÖV at every width >= 768 (they no longer share a column). */
545	.kontakt-card-anchor{
546	  grid-column:2;grid-row:1 / 3;place-self:center;z-index:5;
547	  width:clamp(300px,32vw,460px);aspect-ratio:85/55;perspective:1200px;
548	}
549	@media (max-width:767px){
550	  .kontakt-card-anchor{grid-area:nh;place-self:center;width:80%;}
551	  /* R9 a11y H2 (1.4.10/1.4.12): at 320 the back's content (181 px) overran the fixed 85:55
552	     card (166 px) and pushed "Boka ett möte" outside it. The back keeps the card ratio as a
553	     minimum and grows with its content; the front fills whatever height that gives. */
554	  .kontakt-card-anchor{aspect-ratio:auto;}
555	  .kontakt-card-anchor .kontakt-card-tilt,.kontakt-card-anchor .card-flip2{height:auto;}
556	  .kontakt-card-anchor .face--back{position:relative;aspect-ratio:85/55;overflow:visible;}
557	  .kontakt-card-anchor .card-back-content{height:auto;}
558	}
