561	.card-flip2 button.face{margin:0;padding:6%;font:inherit;text-align:left;cursor:pointer;display:block;width:100%;height:100%;}
562	/* R7 (H9, 1.4.11): black ring, 3:1+ on mint, grey and the white stock alike.
