578	/* ------------------------------------------------------------- resolve (dither -> color) */
579	.img-cell{position:relative;}
580	/* R3: §3 dither -> colour grid-stagger. The tile grid sits over the
581	   already-visible colour layer; each tile shows one slice of the dither
582	   image and fades on its own random-order schedule, so the resolve reads
583	   as pixels dissolving away rather than a wipe. Built once at init from
584	   the existing .dither-layer <img> (see buildTileGrid in the script). */
585	.tile-grid{position:absolute;inset:0;display:grid;pointer-events:none;}
586	.tile-grid > span{display:block;background-repeat:no-repeat;}
587	.is-resolving > .tile-grid > span{will-change:opacity;}
588	.color-layer{clip-path:none;}
