651	      </div>
652	
653	      <div class="card-anchor" id="cardAnchor" aria-hidden="true">
654	        <div class="card-flip" id="cardFlip">
655	          <div class="face face--front">
656	            <div class="photo">
657	              <div class="mark-dock"><svg viewBox="80 400 827 1139" role="presentation" focusable="false"><use href="#alunix-mark-path"></use></svg></div>
658	              <img src="/tests/alunix-concepts-r3/build/assets/k1-stage-pool.webp" width="1600" height="1067" alt="" loading="eager">
