673	  <!-- ============================================================ TES -->
674	  <section id="tes">
675	    <div class="cell tes-top">
676	      <!-- R9 §2: two statements, one ground, a choreographed hand-over, NOT a list beside a screenshot -->
677	      <div class="tes-stage">
678	        <h2 class="headline-50 tes-a">Det första intrycket är digitalt.</h2>
679	        <p class="headline-50 tes-b"><span class="tes-b-text" aria-hidden="true">Vi hjälper er att synas på rätt sätt.</span><span class="sr-only">Vi hjälper er att synas på rätt sätt.</span></p>
