688	    <div class="g g12 process-row">
689	      <div class="c-6 cell process-left">
690	        <div class="process-sticky">
691	          <p class="process-kicker mono">Vår process:</p>
692	          <h2 class="process-title headline-40">Från samtal till lanserad sida.</h2>
693	          <p class="process-lock body">Webbdesign, design och system. Allt på ett ställe.</p>
694	          <div class="process-image img-cell" data-resolve="process" style="background:var(--grey)">
695	            <img class="dither-layer" src="assets/dither/k4-cabin-desk-dither-grey.webp" alt="" loading="lazy">
696	            <img class="color-layer" src="/tests/alunix-concepts-r3/build/assets/k4-cabin-desk.webp" alt="Ett skrivbord i en stuga" loading="lazy" style="clip-path:inset(0 100% 0 0)">
