      </div>
      <div class="hero-cell hero-oh img-cell" data-resolve="stay">
        <img class="dither-layer" src="assets/dither/k1-stage-pool-dither-grey.webp" alt="En ljuspöl faller diagonalt över ett mörkt scentyg, rastrerad" loading="eager" fetchpriority="high">
      </div>
      <div class="hero-cell hero-nv img-cell" data-resolve="stay">
        <img class="dither-layer" src="assets/dither/k4-cabin-desk-dither-grey.webp" alt="Ett skrivbord i en stuga, rastrerat" loading="lazy">
      </div>
      <div class="hero-cell hero-nh">
