      </div>

      <div class="card-anchor" id="cardAnchor" aria-hidden="true">
        <div class="card-flip" id="cardFlip">
          <div class="face face--front">
            <div class="photo">
              <div class="mark-dock"><svg viewBox="80 400 827 1139" role="presentation" focusable="false"><use href="#alunix-mark-path"></use></svg></div>
              <img src="/tests/alunix-concepts-r3/build/assets/k1-stage-pool.webp" width="1600" height="1067" alt="" loading="eager">
            </div>
          </div>
          <div class="face face--back">
