input.new_string:
/* ============================================================ §7c R10 materiella övergångar
   Three section changes, each caused by the page's own material, each scrubbed in both
   directions by a progress-only ScrollTrigger (Lenis is the only smoothing):
     T1 process -> showcase  the desk photo grows out of its frame to the showcase frame's
                             size, then dissolves tile by tile into the live site under it
     T2 showcase -> pris     the mint track floods its own surface and opens into the pris
                             ground, which the bento's mint cell continues
     T3 pris -> kontakt      that mint cell contracts into the contact card's shadow
   No iframe is transformed or faded: T1 draws its own layer over the frame and takes it away.
   All three are created after the showcase pin (they read its start/end), and none refreshes. */
var VIEW = function(){ return document.documentElement.clientHeight; };
var VIEWW = function(){ return document.documentElement.clientWidth; };
function lerp(a, b, t){ return a + (b - a) * t; }
function easeIO(t){ return t < 0.5 ? 2 * t * t : 1 - 2 * (1 - t) * (1 - t); }
function clamp01(t){ return t < 0 ? 0 : t > 1 ? 1 : t; }
function lerpRect(a, b, t){ return { x: lerp(a.x, b.x, t), y: lerp(a.y, b.y, t), w: lerp(a.w, b.w, t), h: lerp(a.h, b.h, t) }; }
function insetOf(r){
  var W = VIEWW(), H = VIEW();
  return 'inset(' + r.y.toFixed(1) + 'px ' + (W - r.x - r.w).toFixed(1) + 'px ' + (H - r.y - r.h).toFixed(1) + 'px ' + r.x.toFixed(1) + 'px)';
}
function rectOf(el, pad){
  var b = el.getBoundingClientRect(); pad = pad || 0;
  return { x: b.left + pad, y: b.top + pad, w: b.width - 2 * pad, h: b.height - 2 * pad };
}
/* the frame's natural document top in the stacked layout, where it is position:sticky: the
   visible case head sits directly above it (1 px seam), and the head never sticks */
function stackedFrameStart(){
  var head = CASES[activeCaseKey].el.querySelector('.showcase-head');
  return head ? Math.round(head.getBoundingClientRect().bottom + 1 + lenis.scroll - 48) : 0;
}
function handoverScroll(){ return (isPinLayout() && showcaseST) ? showcaseST.start : stackedFrameStart(); }

/* ---------- T1: the desk photo grows into the frame, then dissolves into the site */
var processImage = document.querySelector('.process-image');
var embedCell = document.querySelector('.showcase-embed-cell');
var GROW_SRC = '/tests/alunix-concepts-r3/build/assets/k4-cabin-desk.webp', GROW_W = 733, GROW_H = 1100;
var GROW_SPLIT = 0.6; /* first 60 % of the range: the grow; the rest: the dissolve */
var growPlate = document.createElement('div');
growPlate.className = 'grow-plate';
growPlate.setAttribute('aria-hidden', 'true');
var growImg = new Image();
growImg.alt = ''; growImg.src = GROW_SRC; growImg.width = GROW_W; growImg.height = GROW_H;
growImg.style.width = GROW_W + 'px'; growImg.style.height = GROW_H + 'px';
growPlate.appendChild(growImg);
document.body.appendChild(growPlate);
var growTiles = document.createElement('div');
growTiles.className = 'grow-tiles';
growTiles.setAttribute('aria-hidden', 'true');
embedCell.appendChild(growTiles);
var growTileEls = [], growDims = [0, 0], growDissolve = null;
/* the tiles show the same photo, cover-fitted to the frame exactly as the plate draws it on
   its last grow frame, so the swap from plate to tiles has no seam */
function layoutGrowTiles(){
  var cols = isNarrow ? 6 : 10, rows = isNarrow ? 6 : 10;
  if (growDims[0] !== cols || growDims[1] !== rows){
    growTiles.innerHTML = '';
    growTileEls = [];
    for (var i = 0; i < cols * rows; i++){ var s = document.createElement('span'); s.style.backgroundImage = 'url(' + GROW_SRC + ')'; growTiles.appendChild(s); growTileEls.push(s); }
    growTiles.style.gridTemplateColumns = 'repeat(' + cols + ',1fr)';
    growTiles.style.gridTemplateRows = 'repeat(' + rows + ',1fr)';
    growDims = [cols, rows];
    if (growDissolve) growDissolve.kill();
    /* a diagonal wave from the top left (R6b: a random order left a checkerboard in every still) */
    growDissolve = gsap.timeline({ paused: true });
    growDissolve.to(growTileEls, { opacity: 0, ease: 'none', duration: 0.35, stagger: { grid: [rows, cols], from: 'start', amount: 0.65 } });
    growDissolve.set({}, {}, 1);
  }
  var w = embedCell.clientWidth, h = embedCell.clientHeight;
  var s = Math.max(w / GROW_W, h / GROW_H), bw = GROW_W * s, bh = GROW_H * s, ox = (w - bw) / 2, oy = (h - bh) / 2;
  var tw = w / cols, th = h / rows;
  growTileEls.forEach(function(t, i){
    var c = i % cols, r = Math.floor(i / cols);
    t.style.backgroundSize = bw.toFixed(1) + 'px ' + bh.toFixed(1) + 'px';
    t.style.backgroundPosition = (ox - c * tw).toFixed(1) + 'px ' + (oy - r * th).toFixed(1) + 'px';
  });
}
function drawGrow(r){
