var prisGround = document.querySelector('.pris-ground');
var stageEl = document.querySelector('.showcase-stage');
var mTrack = document.querySelector('.showcase-mtrack');
Object.keys(CASES).forEach(function(k){
  var rows = CASES[k].el.querySelector('.showcase-rows');
  if (!rows) return;
  var f = document.createElement('div');
  f.className = 'showcase-flood';
  f.setAttribute('aria-hidden', 'true');
  rows.appendChild(f);
  CASES[k].flood = f;
});
/* the flood starts on the track line itself */
function placeFloods(){
  Object.keys(CASES).forEach(function(k){
    var C = CASES[k], track = C.el.querySelector('.showcase-track'), rows = C.el.querySelector('.showcase-rows');
    if (!C.flood || !track || !rows || !rows.offsetHeight) return;
    C.flood.style.top = (track.getBoundingClientRect().top - rows.getBoundingClientRect().top) + 'px';
  });
}
/* where the stage lets go: the pin's end, or (stacked) where the sticky frame un-sticks */
function releaseScroll(){
  if (isPinLayout() && showcaseST) return showcaseST.end;
  var sb = stageEl.getBoundingClientRect().bottom + lenis.scroll;
  return Math.round(sb - 48 - embedCell.offsetHeight);
}
function sideOffset(){
  var side = document.querySelector('.showcase-side'), sr = side.getBoundingClientRect(), pr = prisStatement.getBoundingClientRect();
  return Math.max(0, Math.round(sr.left - pr.left));
}
var t2X = 0;
function updateT2(q){
  var pin = isPinLayout();
  Object.keys(CASES).forEach(function(k){
    var f = CASES[k].flood;
    if (f) gsap.set(f, { scaleY: pin ? clamp01(q / 0.45) : 0 });
  });
  if (pin){
    /* down the right column under the flooded rows, then across the whole cell */
    var a = clamp01((q - 0.25) / 0.4), b = clamp01((q - 0.65) / 0.35);
    prisGround.style.clipPath = 'inset(0px 0px ' + ((1 - a) * 100).toFixed(2) + '% ' + (t2X * (1 - b)).toFixed(1) + 'px)';
  } else {
    /* stacked: from the full track on the frame's bottom edge straight down the cell */
    prisGround.style.clipPath = 'inset(0px 0px ' + ((1 - clamp01(q)) * 100).toFixed(2) + '% 0px)';
  }
}
