    trigger: '#showcase', invalidateOnRefresh: true,
    start: function(){ return stackedFrameStart(); },
    end: function(){ return releaseScroll(); },
    onRefresh: function(self){ gsap.set(mTrack, { scaleX: self.progress }); },
    onUpdate: function(self){ gsap.set(mTrack, { scaleX: self.progress }); }
